public static function payment_copy_text( $id ) {
    $data = self::copy_payment_data( $id );
    if ( ! $data ) { return ''; }
    $order_id = absint( get_post_meta( $id, '_tkd_fo_order_id', true ) );
    $order_number = '';
    if ( $order_id && 'tkd_order' === get_post_type( $order_id ) ) {
        $order_number = sanitize_text_field( get_post_meta( $order_id, '_tkd_order_number', true ) );
        if ( '' === $order_number ) { $order_number = str_pad( (string) $order_id, 5, '0', STR_PAD_LEFT ); }
    }
    $intro = "Добрий день!\n\nНадсилаємо рахунок для оплати"
        . ( '' !== $order_number ? ' замовлення № ' . $order_number : '' ) . ".\n\n";
    $total_cents = (int) round( (float) get_post_meta( $id, '_tkd_fo_invoice_total', true ) * 100 );
    $reserve_cents = intdiv( $total_cents + 2, 5 );
    return $intro . self::payment_text_from_data( $data ) . "\n\nДля резерву під поставку клієнт сплачує 20% від суми рахунку — "
        . number_format( $reserve_cents / 100, 2, ',', ' ' ) . ' грн.';
}
